(function(){tinymce.PluginManager.requireLangPack('insertimage');tinymce.create('tinymce.plugins.insertimagePlugin',{init:function(ed,url){ed.addCommand('mceinsertimage',function(){ed.windowManager.open({file:url+'/dialog.php',width:320+parseInt(ed.getLang('insertimage.delta_width',0)),height:120+parseInt(ed.getLang('insertimage.delta_height',0)),inline:1},{plugin_url:url,some_custom_arg:'custom arg'})});ed.addButton('insertimage',{title:'insertimage.desc',cmd:'mceinsertimage',image:url+'/img/image.gif'});ed.onNodeChange.add(function(ed,cm,n){cm.setActive('insertimage',n.nodeName=='IMG')})},createControl:function(n,cm){return null},getInfo:function(){return{longname:'insertimage plugin',author:'Some author',authorurl:'http://tinymce.moxiecode.com',infourl:'http://wiki.moxiecode.com/index.php/TinyMCE:Plugins/insertimage',version:"1.0"}}});tinymce.PluginManager.add('insertimage',tinymce.plugins.insertimagePlugin)})();